namespace emon;


public static class Scriptchecktest {
    internal static int SkAnswer(emon.Port.Cells ans, int id, int n, int script, int sconf, int lang, int lang0) {
        // An OCR answer of `n` words, one a line, each read in the language cell `lang` (the first in `lang0`), whose page OSD says is in `script` at the confidence `sconf`.
        int at = Plan.AnOcr(ans, id);
        int k = 0;
        int word = 0;
        while (k < n) {
            word = Plan.AnOcrWord(ans, at, 10, 20 + (k * 60), 60, 40, 760, k, 0);
            Plan.AnOcrCp(ans, word, 72);
            Plan.AnOcrCp(ans, word, 105);
            k += 1;
        }
        Ocr.OxBegin(ans, 0, 0, 0, 0, 0, script, sconf, 500, n, 1, 0, 0, 0);
        k = 0;
        while (k < n) {
            Ocr.OxLine(ans, 10, 20 + (k * 60), 60, 40, 10, 55 + (k * 60), 70, 55 + (k * 60), 0, 0, 0, 20, 14, 6);
            k += 1;
        }
        Ocr.OxBlock(ans, 10, 20, 60, n * 60, 0, 0, 0);
        k = 0;
        while (k < n) {
            if (k == 0) {
                Ocr.OxWord(ans, 0, lang0, -1, 0);
            } else {
                Ocr.OxWord(ans, 0, lang, -1, 0);
            }
            k += 1;
        }
        Plan.AnOcrEnd(ans, at);
        return at;
    }
    internal static int UnreadOf(int n, int script, int sconf, int lang, int lang0) {
        emon.Port.Cells ans = emon.Port.NewCells();
        int at = SkAnswer(ans, 272, n, script, sconf, lang, lang0);
        return Scriptcheck.SkUnread(ans, at, emon.Port.NewCells());
    }
    [Xunit.Fact]
    public static void TestALanguageCellUnpacksToItsLetters() {
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Testport.AssertEq(Scriptcheck.SkUnpack(1701734144, @out), 3, "`eng` is three letters");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 0), 101, "e");
        emon.Testport.AssertEq(emon.Port.CellsAt(@out, 2), 103, "g");
        emon.Testport.AssertEq(Scriptcheck.SkUnpack(0, @out), 0, "none");
    }
    [Xunit.Fact]
    public static void TestAScriptNoModelReadIsUnread() {
        // Deva 1147500129, Latn 1281455214, Cyrl 1132032620; the languages `eng` 1701734144, `hin` 1751739904, `rus` 1920299776
        emon.Testport.AssertEq(UnreadOf(5, 1147500129, 629, 1701734144, 1701734144), 1, "a Devanagari page (OSD 62.9) read by `eng`: unread (the smoke review's Hindi scan)");
        emon.Testport.AssertEq(UnreadOf(5, 1132032620, 400, 1701734144, 1701734144), 1, "a Cyrillic page read by `eng`: unread");
        emon.Testport.AssertEq(UnreadOf(5, 1147500129, 629, 1751739904, 1751739904), 0, "the same read by `hin`, which reads Devanagari: read");
        emon.Testport.AssertEq(UnreadOf(5, 1147500129, 629, 1701734144, 1751739904), 0, "one word read by `hin` is a model that reads it: read");
        emon.Testport.AssertEq(UnreadOf(5, 1132032620, 400, 1920299776, 1920299776), 0, "a Cyrillic page read by `rus`: read");
        emon.Testport.AssertEq(UnreadOf(5, 1147500129, 629, 1920299776, 1920299776), 1, "a Devanagari page read by `rus` (which reads Cyrillic): unread");
    }
    [Xunit.Fact]
    public static void TestAPageTheEngineCanReadOrOsdIsUnsureOfIsNotFlagged() {
        emon.Testport.AssertEq(UnreadOf(5, 1281455214, 629, 1701734144, 1701734144), 0, "a Latin page");
        emon.Testport.AssertEq(UnreadOf(5, 1147500129, 100, 1701734144, 1701734144), 0, "OSD unsure (confidence 10: a Latin page reads that)");
        emon.Testport.AssertEq(UnreadOf(5, 1147500129, Scriptcheck.SkMinConf() - 1, 1701734144, 1701734144), 0, "just under the bound");
        emon.Testport.AssertEq(UnreadOf(5, 1147500129, Scriptcheck.SkMinConf(), 1701734144, 1701734144), 1, "at it");
        emon.Testport.AssertEq(UnreadOf(2, 1147500129, 629, 1701734144, 1701734144), 0, "two words: the engine read nothing of it to speak of");
        emon.Testport.AssertEq(UnreadOf(5, 0, 629, 1701734144, 1701734144), 0, "no script");
    }
    [Xunit.Fact]
    public static void TestAnAnswerWithNoExtensionIsNotFlagged() {
        emon.Port.Cells ans = emon.Port.NewCells();
        int at = Plan.AnOcr(ans, 272);
        int w = Plan.AnOcrWord(ans, at, 10, 20, 60, 40, 760, 0, 0);
        Plan.AnOcrCp(ans, w, 72);
        Plan.AnOcrEnd(ans, at);
        emon.Testport.AssertEq(Scriptcheck.SkUnread(ans, at, emon.Port.NewCells()), 0, "an engine that says nothing of the script");
    }
